/** Project the captured baseline and explicitly reviewed ownership decisions into task reports. */
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import assert from 'node:assert/strict';
import { validateReportStatuses } from './specification-traceability.mjs';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { basename, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '../..');
const baseline = JSON.parse(readFileSync(resolve(root, 'UPSTREAM_DELTA.json'), 'utf8'));
const reviews = JSON.parse(readFileSync(resolve(root, 'artifacts/upstream-first/component-reviews.json'), 'utf8'));
assert.equal(reviews.upstreamSha, baseline.upstream.sha);
const write = (name, value) => writeFileSync(resolve(root, name), value.trimEnd() + '\n');
const json = (name, value) => write(name, JSON.stringify(value, null, 2));
const sourceSha = baseline.upstream.sha;
const desktopContextRecordPath = 'artifacts/upstream-first/desktop-context-source.json';
const digest = path => createHash('sha256').update(readFileSync(resolve(root, path))).digest('hex');
// The approval-facts-complete generation sealed untracked package build outputs at its
// capture-time bytes; gen-31's cordis-catalog regeneration rebuilt the tool-cordis bundle
// (lib/index.js plus the api-catalog type build) and cascaded the subagent type build
// through project references. The rebuild is not byte-stable against the incremental-emit
// state of the sealed build (clean reruns agree on new bytes; the sealed bytes have no
// disk, archive, or committed copy — incremental-emit variance carries no evidence value,
// same rationale as the .tsbuildinfo exclusion). Adjudicated per the
// androidFollowWindowReplacedBuildOutputs precedent: the entries stay recorded verbatim,
// validation treats them as replaced, and the prepare-side ruling pinned exactly these keys.
const approvalFactsCompleteReplacedBuildOutputs = new Set([
  'packages/extensions/tool-cordis/lib/index.js:2c72694cd272530bb6836b97f0e4468d3da8995d77efe7e346467602339f6793',
  'packages/extensions/tool-cordis/lib/types/api-catalog.js:c6effcc52779b9d1567b93417971bc013454922f32ae8fafbd31a419afac3dfa',
  'packages/extensions/tool-cordis/lib/types/api-catalog.js.map:7a8a63b3c309fe09092605688432f15644b7445560e9fdacfa4011a14b555b6b',
  'packages/subagent/subagent/lib/types/control.d.ts:cfea58847218fae7c701bd94127a00fc8b586d820a817333e5cad44fe762972a',
]);
// Adjudicated replaced build outputs for the diagnostics-source-revision increment: its
// cordis-catalog regeneration rebuilt tool-cordis's untracked bundle (lib/index.js plus the
// api-catalog type build). The sealed bytes are incremental-emit history with no archived
// copy (clean reruns agree on new bytes — the prior index.js already rode the a1610cbc
// lineage), so per the androidFollowWindowReplacedBuildOutputs precedent the entries stay
// recorded verbatim, validation treats them as replaced, and the prepare-side ruling
// pinned exactly these keys.
const tornRepairIntentReplacedBuildOutputs = new Set([
  'packages/extensions/tool-cordis/lib/index.js:a1610cbc3d503e963d24e42965612158e42915a3a2ce251bceeeac4f52403fae',
  'packages/extensions/tool-cordis/lib/types/api-catalog.js.map:acbb6b79edf31e4d7f97967c5c13c46764ad7da8d0ad8713936d1f4f929fc790',
  'packages/extensions/tool-cordis/lib/types/api-catalog.js:ab4892841eb8d5db727ae1c17914a1aefc50a1682869743df9f3494375679e54',
]);
const crashDiagnosticsOutletPath = 'artifacts/upstream-first/crash-diagnostics-outlet-source.json';
assert.equal(digest(crashDiagnosticsOutletPath), 'cd829638ccae3154bfb9b15001e5743bf213eb1f12c9a56f70d9195b215e3fc0', 'Crash Diagnostics Outlet source record changed');
const crashDiagnosticsOutlet = JSON.parse(readFileSync(resolve(root, crashDiagnosticsOutletPath), 'utf8'));
assert.equal(crashDiagnosticsOutlet.baseSha, sourceSha);
for (const field of ['sourceFiles', 'builtFiles', 'logs', 'helpers', 'historicalRecords', 'screenshots', 'observations', 'comparisons']) {
  for (const file of crashDiagnosticsOutlet[field].filter(file => !file.path.endsWith('.tsbuildinfo'))) assert.equal(digest(file.path), file.sha256, 'Current Crash Diagnostics Outlet ' + field + ' changed: ' + file.path);
}
for (const path of crashDiagnosticsOutlet.removedPaths) assert.equal(existsSync(resolve(root, path)), false, 'Retired entry returned: ' + path);
const crashDiagnosticsOutletHistory = new Map();
for (const record of crashDiagnosticsOutlet.historicalRecords) {
  for (const file of JSON.parse(readFileSync(resolve(root, record.path), 'utf8')).files) {
    assert.equal(digest(file.path), file.sha256, 'Crash Diagnostics Outlet saved input changed: ' + file.path);
    crashDiagnosticsOutletHistory.set(file.originalPath + ':' + file.sha256, file.path);
  }
}


































































